import 'package:flutter/material.dart';
import 'package:just_audio/just_audio.dart';
import 'package:quran/quran.dart' as quran;
import 'package:shared_preferences/shared_preferences.dart';
import 'package:flutter/services.dart';

void main() => runApp(const QuranApp());

class QuranApp extends StatefulWidget { const QuranApp({super.key}); @override State<QuranApp> createState()=> _QuranAppState(); }
class _QuranAppState extends State<QuranApp> {
  double fontSize=22; bool isDark=true; String reciter="عبد الباسط عبد الصمد";
  @override void initState(){ super.initState(); _load(); }
  _load() async { final p=await SharedPreferences.getInstance(); setState((){ fontSize=p.getDouble('font')??22; isDark=p.getBool('dark')??true; reciter=p.getString('reciter')??"عبد الباسط عبد الصمد"; }); }
  @override Widget build(BuildContext context){ return MaterialApp(debugShowCheckedModeBanner: false, theme: isDark? ThemeData.dark(useMaterial3: true).copyWith(scaffoldBackgroundColor: const Color(0xFF0F0F0F)) : ThemeData.light(useMaterial3: true), home: MainPage(fontSize: fontSize, isDark: isDark, reciter: reciter, onSettingsChanged: (f,d,r) async { final p=await SharedPreferences.getInstance(); await p.setDouble('font', f); await p.setBool('dark', d); await p.setString('reciter', r); setState((){ fontSize=f; isDark=d; reciter=r; }); })); }
}

class MainPage extends StatefulWidget { final double fontSize; final bool isDark; final String reciter; final Function(double,bool,String) onSettingsChanged; const MainPage({super.key, required this.fontSize, required this.isDark, required this.reciter, required this.onSettingsChanged}); @override State<MainPage> createState()=> _MainPageState(); }
class _MainPageState extends State<MainPage> { int idx=0; @override Widget build(BuildContext context){ return Scaffold(body: [QuranListPage(fontSize: widget.fontSize, reciter: widget.reciter), const DuaPage(), SettingsPage(fontSize: widget.fontSize, isDark: widget.isDark, reciter: widget.reciter, onChanged: widget.onSettingsChanged)][idx], bottomNavigationBar: BottomNavigationBar(currentIndex: idx, onTap: (i)=> setState(()=> idx=i), selectedItemColor: const Color(0xFFD4AF37), backgroundColor: widget.isDark? const Color(0xFF1A1A1A) : Colors.white, items: const [BottomNavigationBarItem(icon: Icon(Icons.menu_book), label: "القرآن"), BottomNavigationBarItem(icon: Icon(Icons.favorite), label: "أدعية"), BottomNavigationBarItem(icon: Icon(Icons.settings), label: "الإعدادات")])); } }

class QuranListPage extends StatelessWidget { final double fontSize; final String reciter; const QuranListPage({super.key, required this.fontSize, required this.reciter}); @override Widget build(BuildContext context){ return Scaffold(appBar: AppBar(title: const Text("القرآن الكريم"), centerTitle: true, backgroundColor: const Color(0xFF151515)), body: ListView.builder(itemCount: 114, itemBuilder: (c,i){ int n=i+1; return Card(color: const Color(0xFF1E1E1E), margin: const EdgeInsets.symmetric(horizontal:10, vertical:4), child: ListTile(leading: CircleAvatar(backgroundColor: const Color(0xFFD4AF37), child: Text("$n", style: const TextStyle(color: Colors.black))), title: Text(quran.getSurahNameArabic(n), style: const TextStyle(color: Colors.white, fontWeight: FontWeight.bold)), subtitle: Text("${quran.getVerseCount(n)} آية", style: const TextStyle(color: Colors.white38, fontSize:11)), trailing: const Icon(Icons.play_circle, color: Color(0xFFD4AF37)), onTap: ()=> Navigator.push(c, MaterialPageRoute(builder: (_)=> SurahReaderPage(surahNumber:n, fontSize:fontSize, selectedReciter:reciter))))); })); } }

class SurahReaderPage extends StatefulWidget { final int surahNumber; final double fontSize; final String selectedReciter; const SurahReaderPage({super.key, required this.surahNumber, required this.fontSize, required this.selectedReciter}); @override State<SurahReaderPage> createState()=> _SurahReaderPageState(); }
class _SurahReaderPageState extends State<SurahReaderPage> {
  final player=AudioPlayer(); bool isPlaying=false, loading=false; int curVerse=0; late String reciter;
  final Map<String,String> codes={"عبد الباسط عبد الصمد":"Abdul_Basit_Murattal_192kbps","محمد صديق المنشاوي":"Minshawy_Murattal_128kbps","ياسر الدوسري":"Yasser_Ad-Dosari_128kbps"};
  @override void initState(){ super.initState(); reciter=widget.selectedReciter; player.currentIndexStream.listen((i){ if(i!=null) setState(()=> curVerse=i+1); }); player.playerStateStream.listen((s){ if(s.processingState==ProcessingState.completed) setState((){ isPlaying=false; curVerse=0; }); }); }
  play() async { if(isPlaying){ await player.pause(); setState(()=> isPlaying=false); return; } if(player.audioSource!=null && curVerse>0){ await player.play(); setState(()=> isPlaying=true); return; } setState(()=> loading=true); try{ int cnt=quran.getVerseCount(widget.surahNumber); List<AudioSource> src=[]; for(int i=1;i<=cnt;i++){ String sid=widget.surahNumber.toString().padLeft(3,'0'); String vid=i.toString().padLeft(3,'0'); src.add(AudioSource.uri(Uri.parse("https://everyayah.com/data/${codes[reciter]}/$sid$vid.mp3"))); } await player.setAudioSource(ConcatenatingAudioSource(children: src)); await player.play(); setState((){ isPlaying=true; loading=false; curVerse=1; }); }catch(e){ setState(()=> loading=false); ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text("يحتاج انترنت للصوت"))); } }
  @override void dispose(){ player.dispose(); super.dispose(); }
  @override Widget build(BuildContext context){ int cnt=quran.getVerseCount(widget.surahNumber); return Scaffold(appBar: AppBar(title: Text(quran.getSurahNameArabic(widget.surahNumber))), body: Column(children: [Container(padding: const EdgeInsets.all(10), color: const Color(0xFF1A1A1A), child: Row(children: [loading? const CircularProgressIndicator(color: Color(0xFFD4AF37)) : IconButton(icon: Icon(isPlaying? Icons.pause_circle_filled : Icons.play_circle_filled, size:50, color: const Color(0xFFD4AF37)), onPressed: play), const SizedBox(width:10), Expanded(child: Text(reciter, style: const TextStyle(color: Colors.white70, fontSize:12)))] )), Expanded(child: ListView.builder(padding: const EdgeInsets.all(12), itemCount: cnt+1, itemBuilder: (c,i){ if(i==cnt){ return Container(margin: const EdgeInsets.only(top:30,bottom:40), padding: const EdgeInsets.all(20), decoration: BoxDecoration(color: Colors.black, borderRadius: BorderRadius.circular(15), border: Border.all(color: const Color(0xFFD4AF37), width:1.5)), child: const Column(children: [Text("الفاتحة الى روح المرحوم", style: TextStyle(color: Color(0xFFD4AF37))), Text("ناصر عزيز", style: TextStyle(color: Colors.white, fontSize:24, fontWeight: FontWeight.bold)), Divider(color: Color(0xFFD4AF37)), Text("بِسْمِ اللهِ الرَّحْمٰنِ الرَّحِيمِ\nالْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ\nالرَّحْمٰنِ الرَّحِيمِ\nمَالِكِ يَوْمِ الدِّينِ\nإِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ\nاهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ\nصِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ", textAlign: TextAlign.center, style: TextStyle(color: Colors.white, height:1.9, fontSize:18))])); } bool cur=curVerse==i+1 && isPlaying; return Container(padding: const EdgeInsets.symmetric(vertical:12), decoration: BoxDecoration(color: cur? const Color(0xFFD4AF37).withOpacity(0.15):Colors.transparent, border: const Border(bottom: BorderSide(color: Colors.white10))), child: Text(quran.getVerse(widget.surahNumber, i+1, verseEndSymbol:true), textAlign: TextAlign.right, style: TextStyle(fontSize: widget.fontSize, height:1.9, color: cur? const Color(0xFFD4AF37):null))); })), ])); }
}

class DuaPage extends StatelessWidget { const DuaPage({super.key}); @override Widget build(BuildContext context){ final adya=[{"title":"دعاء للمرحوم ناصر عزيز","text":"اللهم اغفر لناصر عزيز وارحمه وعافه واعف عنه وأكرم نزله ووسع مدخله واغسله بالماء والثلج والبرد ونقه من الخطايا كما نقيت الثوب الأبيض من الدنس\n\nاللهم اجعل قبره روضة من رياض الجنة"}, {"title":"أذكار الصباح","text":"أصبحنا وأصبح الملك لله والحمد لله لا إله إلا الله وحده لا شريك له"}, {"title":"أذكار المساء","text":"أمسينا وأمسى الملك لله والحمد لله"}, {"title":"دعاء للموتى","text":"اللهم ارحم موتانا وموتى المسلمين"}]; return Scaffold(appBar: AppBar(title: const Text("أدعية وأذكار"), centerTitle: true), body: ListView.builder(padding: const EdgeInsets.all(12), itemCount: adya.length, itemBuilder: (c,i)=> Card(margin: const EdgeInsets.only(bottom:12), color: const Color(0xFF1E1E1E), child: Padding(padding: const EdgeInsets.all(16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(adya[i]["title"]!, style: const TextStyle(color: Color(0xFFD4AF37), fontWeight: FontWeight.bold, fontSize:18)), const Divider(color: Colors.white12), Text(adya[i]["text"]!, textDirection: TextDirection.rtl, style: const TextStyle(height:1.8, fontSize:16), textAlign: TextAlign.right)]))))); } }

