  final double fontSize; final bool isDark; final String reciter; final Function(double,bool,String) onChanged;
  const SettingsPage({super.key, required this.fontSize, required this.isDark, required this.reciter, required this.onChanged});
  void _contactDialog(BuildContext context){ showDialog(context: context, builder: (_)=> AlertDialog(backgroundColor: const Color(0xFF1E1E1E), title: const Text("مراسلة المطور", style: TextStyle(color: Color(0xFFD4AF37))), content: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [const Text("في حال واجهت مشكلة أو اقتراح تواصل:", style: TextStyle(color: Colors.white70)), const SizedBox(height:15), _row(Icons.email, "إيميل", "noor.alquloob.app@gmail.com"), _row(Icons.bug_report, "الإبلاغ", "اذكر اسم السورة ورقم الآية"), const SizedBox(height:10), const Text("سيتم الرد بأقرب وقت إن شاء الله", style: TextStyle(color: Colors.white38, fontSize:11))]), actions: [TextButton(onPressed: ()=> Navigator.pop(context), child: const Text("إغلاق", style: TextStyle(color: Color(0xFFD4AF37)))), ElevatedButton(style: ElevatedButton.styleFrom(backgroundColor: const Color(0xFFD4AF37)), onPressed: (){ Clipboard.setData(const ClipboardData(text: "noor.alquloob.app@gmail.com")); Navigator.pop(context); ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text("تم نسخ الإيميل"))); }, child: const Text("نسخ الإيميل", style: TextStyle(color: Colors.black)))])); }
