  @override Widget build(BuildContext context){ return Scaffold(appBar: AppBar(title: const Text("الإعدادات"), centerTitle: true), body: ListView(padding: const EdgeInsets.all(16), children: [
    Card(color: const Color(0xFF1E1E1E), child: Padding(padding: const EdgeInsets.all(16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [const Text("حجم خط القرآن", style: TextStyle(fontWeight: FontWeight.bold)), Slider(value: fontSize, min:16, max:32, divisions:8, activeColor: const Color(0xFFD4AF37), onChanged: (v)=> onChanged(v,isDark,reciter))]))),
    Card(color: const Color(0xFF1E1E1E), child: SwitchListTile(title: const Text("الوضع الليلي"), value: isDark, activeColor: const Color(0xFFD4AF37), onChanged: (v)=> onChanged(fontSize,v,reciter))),
    Card(color: const Color(0xFF1E1E1E), child: Padding(padding: const EdgeInsets.all(16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [const Text("القارئ الافتراضي", style: TextStyle(fontWeight: FontWeight.bold)),...["عبد الباسط عبد الصمد","محمد صديق المنشاوي","ياسر الدوسري"].map((r)=> RadioListTile(value:r, groupValue:reciter, title: Text(r, style: const TextStyle(fontSize:14)), activeColor: const Color(0xFFD4AF37), onChanged: (v)=> onChanged(fontSize,isDark,v!))) ]))),
    const SizedBox(height:15),
    Card(color: const Color(0xFFD4AF37).withOpacity(0.15), child: ListTile(leading: const Icon(Icons.support_agent, color: Color(0xFFD4AF37), size:30), title: const Text("مراسلة المطور", style: TextStyle(fontWeight: FontWeight.bold, color: Color(0xFFD4AF37))), subtitle: const Text("في حال وجود مشكلة أو اقتراح", style: TextStyle(fontSize:11)), trailing: const Icon(Icons.arrow_forward_ios, size:16, color: Color(0xFFD4AF37)), onTap: ()=> _contactDialog(context))),
    const SizedBox(height:10),
    Card(color: const Color(0xFF1E1E1E), child: Column(children: [
      ListTile(leading: const Icon(Icons.share, color: Colors.white70), title: const Text("مشاركة التطبيق"), subtitle: const Text("شارك الأجر", style: TextStyle(fontSize:11)), onTap: (){ Clipboard.setData(const ClipboardData(text: "حمل تطبيق نور القلوب - صدقة لروح المرحوم ناصر عزيز\ncom.noor.nasseraziz")); ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text("تم نسخ رابط المشاركة"))); }),
      const Divider(color: Colors.white10, height:1),
      ListTile(leading: const Icon(Icons.cleaning_services, color: Colors.white70), title: const Text("مسح الإعدادات"), onTap: () async { final p=await SharedPreferences.getInstance(); await p.clear(); onChanged(22,true,"عبد الباسط عبد الصمد"); ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text("تم مسح الإعدادات"))); }),
      const Divider(color: Colors.white10, height:1),
      ListTile(leading: const Icon(Icons.info_outline, color: Colors.white70), title: const Text("سياسة الخصوصية"), onTap: ()=> showDialog(context: context, builder: (_)=> const AlertDialog(backgroundColor: Color(0xFF1E1E1E), title: Text("الخصوصية", style: TextStyle(color: Color(0xFFD4AF37))), content: Text("التطبيق لا يجمع أي بيانات. الصوت يحتاج انترنت فقط.", style: TextStyle(color: Colors.white70))))),
    ])),
